void pop(final String descriptor) {
    // Assuming the method descriptor is in the format of a method descriptor from the JVM spec
    // e.g., "(I)V" for a method that takes an int and returns void
    if (descriptor.charAt(0) == '(') {
        // It's a method descriptor, find the end of the argument types
        int endArgsIndex = descriptor.indexOf(')');
        if (endArgsIndex != -1) {
            String argTypes = descriptor.substring(1, endArgsIndex);
            int i = 0;
            while (i < argTypes.length()) {
                char c = argTypes.charAt(i);
                switch (c) {
                    case 'B': case 'C': case 'I': case 'S': case 'Z':
                        // These types are represented by a single character and take up one slot
                        // in the operand stack (int, short, byte, char, boolean)
                        pop();
                        i++;
                        break;
                    case 'D': case 'J':
                        // These types are represented by a single character and take up two slots
                        // in the operand stack (double, long)
                        pop();
                        pop();
                        i++;
                        break;
                    case 'L':
                        // This is the start of a reference type, which takes up one slot
                        // We need to find the end of the class name
                        int classEndIndex = argTypes.indexOf(';', i);
                        if (classEndIndex != -1) {
                            pop();
                            i = classEndIndex + 1;
                        } else {
                            // Malformed descriptor, just break the loop
                            i++;
                        }
                        break;
                    case '[':
                        // This is an array type, which takes up one slot
                        // We need to skip the array dimensions and type
                        int arrayEndIndex = i;
                        while (arrayEndIndex < argTypes.length() && argTypes.charAt(arrayEndIndex) == '[') {
                            arrayEndIndex++;
                        }
                        if (arrayEndIndex < argTypes.length()) {
                            char arrayType = argTypes.charAt(arrayEndIndex);
                            if (arrayType == 'L') {
                                // Object array, need to find the end of the class name
                                arrayEndIndex = argTypes.indexOf(';', arrayEndIndex);
                            }
                            if (arrayEndIndex != -1) {
                                pop();
                                i = arrayEndIndex + 1;
                            } else {
                                // Malformed descriptor, just break the loop
                                i++;
                            }
                        } else {
                            // Malformed descriptor, just break the loop
                            i++;
                        }
                        break;
                    default:
                        // Unknown type, just skip it
                        i++;
                        break;
                }
            }
        }
    } else {
        // It's a field descriptor, just pop one
        pop();
    }
}

