String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder output = new StringBuilder();
    int length = str.length();
    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (++i >= length) {
                throw new Exception("Invalid escape sequence");
            }
            c = str.charAt(i);
            switch (c) {
                case 'b':
                    output.append('\b');
                    break;
                case 't':
                    output.append('\t');
                    break;
                case 'n':
                    output.append('\n');
                    break;
                case 'f':
                    output.append('\f');
                    break;
                case 'r':
                    output.append('\r');
                    break;
                case '"':
                    output.append('"');
                    break;
                case '\'':
                    output.append('\'');
                    break;
                case '\\':
                    output.append('\\');
                    break;
                default:
                    throw new Exception("Invalid escape sequence");
            }
        } else {
            output.append(c);
        }
    }
    return output.toString();
}

